"Все грани собраны. Финал — через {0}: во всех Разломах мира будет ждать Кощей.":"모든 면을 모았어요. 결전은 {0} 후예요. 세상의 모든 균열에서 코셰이가 기다릴 거예요.",
"Открылась новая мифология — «{0}». Начался сезон {1}.":"새로운 신화 ‘{0}’이(가) 열렸어요. 시즌 {1}이(가) 시작됐어요.",
"Какой мир открылся — Орден узнает с обновлением игры. Начался сезон {0}.":"어떤 세계가 열렸는지는 게임 업데이트 때 기사단이 알게 돼요. 시즌 {0}이(가) 시작됐어요.",
"Эта грань — мифологии, которой ещё нет в игре: она откроется с обновлением. Осколки копятся.":"이 면은 아직 게임에 없는 신화의 것이에요. 업데이트 때 열려요. 조각은 계속 쌓여요.",
