"Духи мифологии «{0}» встречаются в {1} раза чаще. Осталось {2}":"‘{0}’ 신화의 정령이 {1}배 더 자주 나타나요. {2} 남았어요",
"{0} распутывается":"{0}이 풀리고 있어요",
"Грань собрана! Духи мифологии «{0}» станут встречаться чаще через {1}":"한 면을 모았어요! ‘{0}’ 신화의 정령이 {1} 후부터 더 자주 나타나요",
"Мифология сезона {0}. Кощей вот-вот расколет камень — и из трещины выйдет новый мир.":"시즌 {0}의 신화예요. 곧 코셰이가 돌을 쪼개고, 틈새에서 새로운 세계가 나타나요.",
"Мифология сезона {0}. Когда Орден соберёт все {1} граней, Кощей придёт за камнем и расколет его — и из трещины выйдет новый мир.":"시즌 {0}의 신화예요. 기사단이 {1}면을 모두 모으면 코셰이가 돌을 노리고 와서 쪼개요. 그러면 틈새에서 새로운 세계가 나타나요.",
"Множитель Ордена ×{0} — активных Ловчих {1}+ уровня: {2}":"기사단 배율 ×{0} — {1}레벨 이상 활동 사냥꾼: {2}명",
