"Мифология сезона {0}: откроется, когда Кощей расколет камень":"시즌 {0}의 신화: 코셰이가 돌을 쪼개면 열려요",
"В сезоне {0} у камня {1} граней — по одной на каждую мифологию. Новая мифология сезона — последняя грань. Всего за сезон — {2} осколков.":"시즌 {0}의 돌은 {1}면이고, 신화마다 한 면씩이에요. 이번 시즌의 새 신화는 마지막 면이에요. 한 시즌에 모두 {2}개의 조각이 필요해요.",
"Награда за сезон":"시즌 보상",
"Принеси в камень хотя бы один осколок — и Орден наградит тебя в конце сезона.":"돌에 조각을 하나라도 가져오세요. 시즌이 끝나면 기사단이 보상을 줘요.",
"До ступени «{0}» — ещё {1}.":"‘{0}’ 단계까지 {1} 남았어요.",
