"Летопись пока пуста: Орден ещё не собрал ни одной грани.":"기록이 아직 비어 있어요. 기사단이 아직 한 면도 모으지 못했어요.",
"Каждый осколок Алатыря, найденный любым Ловчим, — в разломах и у хранителей-старейшин Капищ, — ложится в общий камень Ордена. Собрана грань — дорога в её мир распутана: {0} дня духи этой мифологии встречаются в {1} раза чаще, у всех Ловчих разом. Собраны все грани сезона — приходит Кощей: {2} дней он ждёт во всех Разломах мира, а потом раскалывает камень. Из трещины выходит новая мифология, начинается новый сезон — и в Лиге тоже. В новом сезоне у камня на одну грань больше.":"어느 사냥꾼이 찾은 알라티르 조각이든, 균열에서든 카피셰의 장로 수호자에게서든, 모두 기사단의 공동 돌에 모여요. 한 면이 모이면 그 세계로 가는 길이 풀려요. {0}일 동안 그 신화의 정령이 모든 사냥꾼에게 동시에 {1}배 더 자주 나타나요. 시즌의 모든 면이 모이면 코셰이가 와요. {2}일 동안 세상의 모든 균열에서 기다리다가 돌을 쪼개요. 틈새에서 새로운 신화가 나오고 새 시즌이 시작돼요. 리그도 마찬가지예요. 새 시즌의 돌은 면이 하나 더 많아요.",
