"Изменить":"변경",
"Начать бой":"전투 시작",
"Здоровье босса растёт с каждым Ловчим, награда — у каждого своя.":"사냥꾼이 늘수록 보스 체력도 늘어나요. 보상은 각자 받아요.",
"Ждём, когда хозяин начнёт бой…":"방장이 전투를 시작하길 기다리는 중…",
"хозяин":"방장",
"(ты)":"(나)",
