"Идём закрывать разлом в Духолове! «Меню → Друзья» → «Совместный разлом» → код: {0}":"두홀로프에서 같이 균열 닫으러 가요! ‘메뉴 → 친구’ → ‘협동 균열’ → 코드: {0}",
