"Источники":"원천",
"Редкие духи":"희귀 정령",
"Необычные духи":"고급 정령",
"Обычные духи":"일반 정령",
"Европа":"유럽",
"Здесь сходятся старые дороги Нави, Олимпа, Асгарда и холмов сидов — от Москвы до Дублина.":"나브, 올림포스, 아스가르드, 시드의 언덕으로 가는 옛길이 여기서 만나요. 모스크바부터 더블린까지요.",
"Азия":"아시아",
"От Уральских гор до Тихого океана. Отсюда родом небесные драконы Китая, а Сибирь и Средняя Азия — края славянских духов.":"우랄산맥부터 태평양까지. 중국의 하늘 용이 여기서 왔고, 시베리아와 중앙아시아는 슬라브 정령의 땅이에요.",
"Африка":"아프리카",
"Здесь, у Нила, стоят врата Дуата — родины египетских богов и духов пустыни.":"이곳 나일강 가에는 이집트 신들과 사막 정령의 고향, 두아트의 문이 서 있어요.",
"Северная Америка":"북아메리카",
"Земля пернатых змеев: из долины Мехико вышли ацтекские боги и духи.":"깃털 달린 뱀의 땅. 아즈텍의 신과 정령들이 멕시코 계곡에서 나왔어요.",
"Южная Америка":"남아메리카",
"Сельва, Анды и Амазонка. Ацтекские духи разлетелись и сюда — до самой Огненной Земли.":"밀림과 안데스, 아마존. 아즈텍 정령들이 여기까지 흩어졌어요. 티에라델푸에고까지요.",
"Австралия и Океания":"오스트레일리아와 오세아니아",
"Своих мифологий у Ордена здесь пока нет: все духи Австралии и Океании — гости, которых занесла Перепутица.":"기사단이 아는 이 땅의 신화는 아직 없어요. 오스트레일리아와 오세아니아의 정령은 모두 대혼선이 데려온 손님이에요.",
"Антарктида":"남극 대륙",
"Здесь только пингвины и ледяные духи. Врата сюда не открываются — слишком холодно даже для Ловчих.":"여기엔 펭귄과 얼음 정령뿐이에요. 문은 이곳으로 열리지 않아요. 사냥꾼에게도 너무 추우니까요.",
"Миров духов всегда было много — у каждого народа свой: Навь у славян, царство Аида у греков, Асгард у скандинавов, холмы сидов у кельтов, Дуат у египтян, Небеса у китайцев, Миктлан у ацтеков. На местах их держал <b>Алатырь</b> — бел-горюч камень в середине всех миров. Каждые врата вели в свою землю, и духи не путали дорог.":"정령의 세계는 언제나 여럿이었어요. 민족마다 자기 세계가 있었죠. 슬라브의 나브, 그리스의 하데스 왕국, 북유럽의 아스가르드, 켈트의 요정의 언덕, 이집트의 두아트, 중국의 천계, 아스테카의 믹틀란. 이 세계들을 제자리에 붙들어 둔 건 모든 세계의 한가운데 있는 불타는 흰 돌, <b>알라티르</b>였어요. 문마다 제 땅으로 이어졌고, 정령들은 길을 헷갈리는 법이 없었어요.",
"Однажды осенней ночью Кощей Бессмертный решил спрятать свою смерть понадёжнее — прямо в сердце Алатыря. Камень треснул и раскололся. Все врата распахнулись разом, дороги между мирами спутались в клубок, и духи и боги семи мифологий высыпали в наш мир — кто куда. Эту ночь назвали <b>Перепутицей</b>. Кощей уверяет, что камень треснул сам, но Локи и Сунь Укун при этих словах почему-то хихикают.":"어느 가을밤, 불사신 코셰이는 자기 죽음을 더 안전한 곳에 숨기기로 했어요. 바로 알라티르의 심장 속에요. 돌은 금이 가더니 쪼개지고 말았어요. 모든 문이 한꺼번에 열리고, 세계와 세계 사이의 길은 실타래처럼 엉켜 버렸어요. 일곱 신화의 정령과 신들은 우리 세상으로 쏟아져 사방으로 흩어졌죠. 그 밤을 <b>대혼선</b>이라고 불러요. 코셰이는 돌이 저절로 갈라졌다고 우기지만, 그 말만 나오면 로키와 손오공이 왠지 킥킥대요.",
"Теперь Гиппокамп плещется в московском фонтане, Леший гуляет по токийскому парку, а Ниссе греет котов в подъездах Каира. Любого духа можно встретить в любом уголке земли. Разломы — трещины от расколотого камня — открываются в каждом городе, а боги ставят святилища там, где осели: Капище по соседству с Пагодой, Храм через улицу от Пирамиды. Город рождает и своих, новых духов: Вайфайку, Трамвайника, Фонарника.":"이제 히포캄포스는 모스크바의 분수에서 물장구를 치고, 레시는 도쿄의 공원을 산책하고, 니세는 카이로의 계단참에서 고양이들을 데워 줘요. 어떤 정령이든 지구 어디에서나 만날 수 있어요. 깨진 돌이 남긴 틈인 균열은 모든 도시에서 열리고, 신들은 자리 잡은 곳에 성소를 세워요. 탑 옆에 카피셰가, 피라미드 길 건너에 신전이 서는 식이죠. 도시는 스스로 새로운 정령도 낳아요. 바이파이카, 트람바이니크, 포나르니크처럼요.",
"Первыми с гостями поладили не учёные, а бабушки со своими оберегами: оказалось, оберег, сделанный с заботой, успокаивает любого духа, откуда бы тот ни был. Так появился <b>Орден Оберега</b> — союз Ловчих всех земель. Твоя задача — находить духов, ловить их оберегами, черпать силу из источников, закрывать разломы и собирать осколки Алатыря. Кто знает — может, однажды их хватит, чтобы распутать дороги домой.":"손님들과 가장 먼저 친해진 건 과학자가 아니라 부적을 든 할머니들이었어요. 정성껏 만든 부적은 어디서 온 정령이든 진정시킨다는 게 밝혀졌거든요. 그렇게 온 땅의 사냥꾼이 모인 <b>부적 기사단</b>이 생겨났어요. 할 일은 정령을 찾아 부적으로 잡고, 원천에서 힘을 얻고, 균열을 닫고, 알라티르 조각을 모으는 거예요. 누가 알아요? 언젠가 조각이 충분히 모이면 집으로 가는 길을 풀 수 있을지도요.",
