"Вышла новая версия приложения Духолов для Android. Скачайте её и установите поверх текущей — прогресс сохранится.":"Android용 두홀로프 앱의 새 버전이 나왔어요. 다운로드해서 현재 앱 위에 설치하세요. 진행 상황은 유지돼요.",
